        override fun callback(`uniffiHandle`: Long,`serial`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeDeviceEvents.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onArrived`(
                    FfiConverterString.lift(`serial`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `onDeparted`: UniffiCallbackInterfaceDeviceEventsMethod1 {
        override fun callback(`uniffiHandle`: Long,`serial`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeDeviceEvents.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onDeparted`(
                    FfiConverterString.lift(`serial`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeDeviceEvents.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceDeviceEvents.UniffiByValue(
        `onArrived`,
        `onDeparted`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_dspi_core_fn_init_callback_vtable_deviceevents(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeDeviceEvents: FfiConverter<DeviceEvents, Pointer> {
    internal val handleMap = UniffiHandleMap<DeviceEvents>()

    override fun lower(value: DeviceEvents): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): DeviceEvents {
        return DeviceEventsImpl(value)
    }

    override fun read(buf: ByteBuffer): DeviceEvents {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: DeviceEvents) = 8UL

    override fun write(value: DeviceEvents, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


// This template implements a class for working with a Rust struct via a Pointer/Arc<T>
// to the live Rust struct on the other side of the FFI.
//
// Each instance implements core operations for working with the Rust `Arc<T>` and the
// Kotlin Pointer to work with the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque pointer to the underlying Rust struct.
//     Method calls need to read this pointer from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its pointer should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the pointer, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the pointer, but is interrupted
//      before it can pass the pointer over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read pointer value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * The embedder API. Create one per app with [`DspiCore::new`].
 *
 * Every call that touches the device blocks its thread for the transfers it
 * makes, so a binding calls these off its UI thread.
 */
public interface DspiCoreInterface {
    
    /**
     * The unit's audio link as the connect probe found it, without
     * traffic: `None` when the device has no alink (stock firmware, the fork
     * without it, role 0, a protocol version this build does not speak, or
     * a hub that refused the read). `Disconnected` without a device.
     */
    fun `alinkInfo`(): AlinkInfo?
    
    /**
     * Write the audio link delays and hop offsets the system delay asks for to
     * every unit (`system.align` with `apply`). Each unit re-anchors: a
     * short silence (2 to 6 ms). Admin only. Blocks while the hub writes
     * every unit.
     *
     * Errors: as [`Self::alink_system_save`], without `conflict`.
     */
    fun `alinkSystemAlign`(): AlinkSystemAlign
    
    /**
     * Recall scene `scene` (an id from the view) on every unit it names
     * (`system.scene.apply`). A recall the hub took but every device
     * refused (a sender holds one scene at a time) is answered with
     * `taken` false and the words to show, naming the frame it holds.
     * Control or admin.
     *
     * Errors: [`DspiError::Link`] `denied` when the role may not make one of
     * the scene's operations (the hub's words name it), `bad_request` for a
     * scene the model does not have; [`DspiError::Disconnected`].
     */
    fun `alinkSystemRecall`(`scene`: kotlin.String): AlinkSceneRecall
    
    /**
     * Save the "Clock and audio links" edits made on the view of `revision`, as
     * one `system.set` the hub takes only while its model is still at that
     * revision. Returns the new revision. Admin only.
     *
     * Errors: [`DspiError::Link`] `conflict` when the installation changed on
     * the hub meanwhile (nothing is saved; read the view again and edit
     * again), `denied` for another role, `bad_request` for values the hub
     * refuses, with its words; [`DspiError::Disconnected`] with no session.
     */
    fun `alinkSystemSave`(`revision`: kotlin.ULong, `edits`: AlinkSystemEdits): kotlin.ULong
    
    /**
     * The audio link's installation on the hub this session is on: its
     * elements with their alink state, the rooms, the scenes, alarms and a
     * one-line summary. Reads `system.status` (and `system.get` when the
     * model changed). The hub answers the status at most once a second per
     * session; asked sooner, this gives the last view again with `stale`.
     * Blocks on the network: keep it off a UI thread.
     *
     * Errors: [`DspiError::Disconnected`] with no hub session,
     * [`DspiError::Link`] with the hub's code or the client's.
     */
    fun `alinkSystemView`(): AlinkSystemView
    
    /**
     * Write the whole cached state to the device in one bulk transfer:
     * chunked `REQ_SET_ALL_PARAMS_CHUNK` (`0xA3`, at most 2048 bytes and
     * the transport's `max_transfer` per chunk), or single-shot
     * `REQ_SET_ALL_PARAMS` (`0xA1`) over a link without chunked bulk. The
     * device applies it on its main loop once the last byte lands.
     *
     * The write is bracketed with the connection's echo filter, so the
     * `BULK_INVALIDATED` it causes is recognised as our own. On success the
     * mirror is re-decoded from the image that was sent (the codec's clamps
     * applied).
     *
     * Runs under the transport's device lock (`Transport::lock`, a no-op
     * except on DSPi Link, where another console's changes are held off
     * for its duration; PLAN "Link device lock").
     *
     * Errors: [`DspiError::Disconnected`] with no device open, or, like the
     * old core, when no image has been read yet (nothing to apply: call
     * [`DspiCore::fetch_all`] first); [`DspiError::ReadOnly`] when the
     * firmware speaks another wire format; [`DspiError::Locked`] /
     * [`DspiError::Denied`] when the Link hub refuses its lock (nothing is
     * sent); the transport's typed error when a transfer fails (the device
     * then applies nothing).
     */
    fun `applyAllParams`()
    
    /**
     * `EXT_APPLY_AT_FRAME`: run `op` ([`APPLY_OP_MAX`] lists them) on the
     * samples of alink frame `frame`, heard `d_local` frames later on every
     * phase-locked unit at once; a frame already passed runs at once and
     * reports "late". Op 0 cancels every pending op (`frame` ignored). The
     * unit queues up to four.
     *
     * Errors as [`DspiCore::set_alink_slots`]; `InvalidArgument` for an
     * op above [`APPLY_OP_MAX`] or an `arg` or `value` outside its range
     * (unused ones 0; a preset slot 0-9, a master volume of -12800..0
     * hundredths of a dB, a rate code 0-2, an output below 9 and a delay of
     * 0-2047 samples).
     * `Refused` when the queue is full, the alink is not locked, or an
     * output or delay is past the device's.
     */
    fun `applyAtFrame`(`frame`: kotlin.ULong, `op`: kotlin.UByte, `arg`: kotlin.UByte, `value`: kotlin.Short)
    
    /**
     * `EXT_APPLY_AT_FRAME` on time base `time_base`: [`TIME_BASE_ALINK`]
     * (`frame` an alink frame, as [`DspiCore::apply_at_frame`]),
     * [`TIME_BASE_USB_SAMPLE`] (`frame` the unit's USB sample index S) or
     * [`TIME_BASE_BUS_FRAME`] (`frame` a bus frame 0-2047 in bits 0-10 and
     * the sample in it in bits 16-23: the same 8 bytes address the same
     * instant on every unit of one host, up to 1.98 s ahead). Ops and their
     * arguments are [`DspiCore::apply_at_frame`]'s.
     *
     * Errors, with no traffic: `Unsupported` for time base 0 without the
     * alink, 1 or 2 without the USB-direct block; `InvalidArgument` for
     * another time base, a bad bus-frame form, or an op or argument out of
     * range; `ReadOnly`, `Disconnected`. `Refused` when the unit stalls (not
     * phase-locked on the USB time base, a full queue).
     */
    fun `applyAtTimeBase`(`timeBase`: kotlin.UByte, `frame`: kotlin.ULong, `op`: kotlin.UByte, `arg`: kotlin.UByte, `value`: kotlin.Short)
    
    /**
     * Begin an undo group: everything written until the matching
     * [`DspiCore::end_group`] that undo can reverse is one undo step,
     * carrying `label` ([`HistoryEntry::label`]), as a drag is. Use it for
     * one action that writes several values (a linked pair, a Clear All, a
     * routing preset). Groups nest: only the outermost begin starts the
     * step and takes its label, and only the matching end ends it. The
     * group belongs to the connection: a disconnect, another device
     * opened, a re-attach, a re-read ([`DspiCore::fetch_all`]) and a change
     * that ends the history (a preset load, a bulk image, a factory reset)
     * end it at any depth, and an `end_group` after that does nothing.
     * With no device the call is ignored. An empty group records nothing.
     * A write undo cannot reverse stands apart, as in a drag. The group is
     * the connection's, not the thread's: call it on the thread that sends
     * the group's writes, in order with them.
     *
     * A group begun while a drag is marked ([`DspiCore::set_dragging`])
     * joins the drag's step instead of ending it (the step takes the
     * group's label if it had none), and its `end_group` leaves that step
     * open until the drag ends: one drag is one step.
     */
    fun `beginGroup`(`label`: kotlin.String)
    
    /**
     * The device's name as last known, with no traffic, kept as
     * [`DspiCore::cached_input_source_name`] keeps source names. "" when
     * unnamed. Errors: `Unsupported` on firmware without device names;
     * `Disconnected`.
     */
    fun `cachedDeviceName`(): kotlin.String
    
    /**
     * The name of input source `source` as last known, with no traffic: read
     * on connect, kept current by notifications (from any client) and by
     * [`DspiCore::set_input_source_name`], and read again after a lost
     * notification. "" when unnamed. For a client's rows, which would
     * otherwise read over the wire what connect has just read.
     *
     * Errors: `Unsupported` on firmware without source names; `InvalidArgument`
     * for a source past the table; `Disconnected` without a device or before
     * it was probed.
     */
    fun `cachedInputSourceName`(`source`: kotlin.UByte): kotlin.String
    
    /**
     * Whether [`DspiCore::redo`] has a change to apply again. False with no
     * device.
     */
    fun `canRedo`(): kotlin.Boolean
    
    /**
     * Whether [`DspiCore::undo`] has a change to reverse. False with no
     * device.
     */
    fun `canUndo`(): kotlin.Boolean
    
    /**
     * Take the live state as what the active preset holds: from now on
     * [`DspiCore::preset_changes`] lists what differs from it. The core
     * does this itself after a connect, a load, a save, a revert and a
     * factory reset. Without a device, or without an image in this build's
     * format, there is no baseline.
     */
    fun `captureBaseline`()
    
    /**
     * Whether enabling `output` would conflict with Core 1's mode (PDM on
     * the last output and the Core 1 EQ worker exclude each other, and the
     * firmware skips a blocked enable silently). One `REQ_GET_CORE1_CONFLICT`
     * read; a failed read is an error, never "no conflict".
     *
     * Errors: [`DspiError::InvalidArgument`] for an output past the
     * device's output count (`DspState.num_output_channels`);
     * [`DspiError::Disconnected`] with no device; a stall, timeout or other
     * transfer error from the read.
     */
    fun `checkCore1Conflict`(`output`: kotlin.UByte): kotlin.Boolean
    
    /**
     * Clear `EXT_ALINK_USB_DIAG`. Errors as [`DspiCore::set_alink_usb`].
     */
    fun `clearAlinkUsbDiag`()
    
    /**
     * Clear the device's sticky clip flags (`REQ_CLEAR_CLIPS`, which reads
     * the flags back and clears them; the value is not used).
     *
     * Meter housekeeping, not a parameter: it touches no setting and
     * nothing in the bulk image, so it is allowed on a read-only
     * connection too. This is the one named exception (PLAN §1.2) to
     * "state-changing opcodes only on a `Writable`": it goes out on a plain
     * `Connection`.
     *
     * Errors: [`DspiError::Disconnected`] with no device open; the
     * transport's typed error when the transfer fails.
     */
    fun `clearClips`()
    
    /**
     * Close the device opened by [`DspiCore::open_fd`] (the same as
     * [`DspiCore::disconnect`]); afterwards the app may close its
     * `UsbDeviceConnection`. Not called `close` because UniFFI's Kotlin
     * objects already have `close()` (free the object).
     */
    fun `closeFd`()
    
    /**
     * The device's configuration as a `.dspipreset` document (JSON, schema
     * 1), from the mirror: no transfer. `name` and `app_version` go into
     * `meta`; `links` is the app's input-pair link mask (bit p: pair p),
     * written as `global.inputPairLinked`.
     *
     * The document holds what the device's wire format carries: a key or
     * block that firmware lacks is left out, `crossfeed.pairMap` is written
     * only when the device reports a map over the extension channel, and
     * the upmixer only on an RP2350. A read-only device (another wire
     * format) exports what its image showed.
     *
     * Errors: [`DspiError::Disconnected`] with no device;
     * [`DspiError::Transfer`] before its settings were read;
     * [`DspiError::Unsupported`] for firmware whose image this build cannot
     * map.
     */
    fun `configExport`(`name`: kotlin.String, `appVersion`: kotlin.String, `links`: kotlin.UByte): kotlin.String
    
    /**
     * Apply a `.dspipreset` document to the device as one bulk write, under
     * the device lock. `options`: [`IMPORT_VOLUMES`] also applies the master
     * and user volume, [`IMPORT_HARDWARE`] the hardware I/O and the
     * limiters. The crossfeed pair map goes over the extension channel when
     * the device has one.
     *
     * Every setting the document holds no readable value for keeps the
     * device's value: a missing key or block, a value of the wrong type, an
     * `eq` or `crossover` with no entries. A bank with entries replaces the
     * channel's, the rest going flat. Delays past the device's delay line
     * are shortened to it. Channels the device lacks are named, not moved.
     *
     * Returns JSON. On success `{ok: true, error: "", lines, clean, links,
     * hardwareWritten, leftAlone, outOfRange}`: `lines` is the report,
     * `clean` false when anything was missing, skipped, left alone,
     * shortened or out of range, `leftAlone` the keys left alone,
     * `outOfRange` the numbers past what this device takes, each
     * `{path, value, applied}` (registry path with indices, the document's
     * value, the nearest end written instead; WP P0U's rows), `links` the input-pair link mask to
     * restore (null when the document has none), and `hardwareWritten`
     * whether I/O was changed while the device stores its output
     * configuration apart from presets (save that to keep it). Otherwise
     * `{ok: false, error}`: the text is not a document this build reads, or
     * the device could not be written (disconnected, read-only firmware,
     * another console's lock, a failed transfer); the mirror then stays as
     * it was.
     */
    fun `configImport`(`text`: kotlin.String, `options`: kotlin.UInt): kotlin.String
    
    /**
     * [`DspiCore::config_import`] with the EQ narrowed to the wire channels
     * in `eq_channels` (bit k: channel k; `u32::MAX` every one). `options`
     * as there: with [`IMPORT_BY_BLOCK`] each `IMPORT_*` block bit says
     * whether its block is applied (EQ, crossover, routing and matrix,
     * outputs, limiters, effects, volume levels, hardware I/O, names), and
     * a block left out keeps the device's values; without it the old two
     * bits keep their meaning. The reply is `config_import`'s, plus
     * `blocks`: the block bits applied.
     *
     * With [`IMPORT_BY_BLOCK`] and no block bit nothing is chosen: the
     * reply is a refusal (`noticeKey` `config.nothing_selected`) and nothing
     * is written, journalled or logged; the undo history stays as it was.
     */
    fun `configImportSelected`(`text`: kotlin.String, `options`: kotlin.UInt, `eqChannels`: kotlin.UInt): kotlin.String
    
    /**
     * What importing `text` with `options` and `eq_channels` (as
     * [`DspiCore::config_import_selected`] takes them) would change on the
     * device, without writing anything: the preview shown before an import
     * (PRO1 W5). No I/O.
     *
     * Returns [`config_diff`]'s JSON, the device's values as `before`.
     * `{ok: false, error}` for a text that is not a document this build
     * reads, or with no device whose settings have been read.
     */
    fun `configPreview`(`text`: kotlin.String, `options`: kotlin.UInt, `eqChannels`: kotlin.UInt): kotlin.String
    
    /**
     * The open connection's generation: unique per connection and never
     * reused while the process runs, so it changes on every reopen and on
     * a Link re-bind. 0 when nothing is open.
     */
    fun `connectionGeneration`(): kotlin.ULong
    
    /**
     * Copy the live state to `dest` and save it to `source` again, so
     * `source` stays the active preset (the Mac console's "Copy to"). Each
     * save waits for the device; one device lock covers both.
     *
     * If the save to `dest` is not confirmed, nothing more is sent and the
     * baseline stays. After the second save, the live state is the
     * baseline.
     *
     * Errors: the first failing save's (`Refused` with its `PRESET_*`
     * status); [`DspiError::Transfer`] when `dest`'s save was not
     * confirmed; otherwise as [`DspiCore::save_preset`].
     */
    fun `copyPreset`(`source`: kotlin.UByte, `dest`: kotlin.UByte)
    
    /**
     * Whether enabling output `output` would collide on Core 1, and if so
     * why, in the words [`DspiCore::write_param`] refuses it with: `None`
     * when it would not. The device decides
     * ([`DspiCore::check_core1_conflict`]); the words come from the layout.
     *
     * Errors: those of [`DspiCore::check_core1_conflict`].
     */
    fun `core1ConflictReason`(`output`: kotlin.UByte): kotlin.String?
    
    /**
     * Close the flow: the user left. No traffic. `InvalidArgument` during a
     * run, which goes on until ended.
     */
    fun `coreVregCalClose`()
    
    /**
     * Save the voltage that passed, with a `SET`: the one explicit step from
     * a pass to flash. The status is read first, so a hang since the last
     * poll takes the pass back. Read back by later polls: `Committed` or
     * `VerifyFailed`. `typed` is the word when the view's `commit_needs_word`
     * says so, even if it was typed for the trial. A refusal leaves the flow in
     * `Passed`, with the trial running. Errors as for starting.
     */
    fun `coreVregCalCommit`(`typed`: kotlin.String?)
    
    /**
     * Keep a trial found on the device: the soak counts from now, for
     * `soak_s` seconds. A trial outside the flow's range is left alone and
     * cannot pass. Sends nothing. Errors as for opening.
     */
    fun `coreVregCalKeep`(`soakS`: kotlin.UInt)
    
    /**
     * Open the flow: the user reached it, from Advanced. Shows the warning
     * and what is on record; sends no write.
     *
     * `Disconnected`; `Unsupported` without a usable `EXT_CORE_VREG`;
     * `Denied` after a hub refused a write on this connection; `ReadOnly`;
     * `InvalidArgument` during a run.
     */
    fun `coreVregCalOpen`()
    
    /**
     * Read the device and advance the flow; never fails, the view says.
     * Call on every connect and about once a second while the page shows.
     * The only write that can go out is the next step of a run the user
     * started; never a `SET`, and none after the connection changed. Blocks
     * for a read: call it off the UI thread.
     */
    fun `coreVregCalPoll`(): VregCalView
    
    /**
     * Start a run: the current record is cleared, `target` goes on trial
     * once the device shows that, and the soak counts for `soak_s` seconds.
     * `typed` is what the user typed when the view says this needs the word.
     *
     * `OvervoltWordRequired`, with no write, if it does and that is not
     * exactly the word. `InvalidArgument`, with no write, for a voltage
     * outside the build default to 1.25 V, a soak under the minimum, a trial
     * already running, or the wrong phase. `Disconnected`,
     * `Unsupported`, `ReadOnly`; `Refused`, `Denied`, `Locked`, `Transfer` for
     * the write, which is not retried.
     */
    fun `coreVregCalStart`(`target`: kotlin.UByte, `soakS`: kotlin.UInt, `typed`: kotlin.String?)
    
    /**
     * The calibration flow as it stands, from memory: no traffic. It waits
     * for a poll or request in flight, so a slow link can hold it up as long
     * as that read: call it off the UI thread too.
     */
    fun `coreVregCalView`(): VregCalView
    
    /**
     * Play an event on the demo device, for clients' tests and demo mode.
     * `seconds` is for [`VregDemoEvent::AdvanceUptime`]. `Unsupported`, with
     * no traffic, on anything but a simulated device.
     */
    fun `coreVregDemoEvent`(`event`: VregDemoEvent, `seconds`: kotlin.UInt)
    
    /**
     * Manual `AUTO`: the firmware's automatic raising after repeated hangs.
     * Errors as for starting.
     */
    fun `coreVregManualAuto`(`on`: kotlin.Boolean)
    
    /**
     * Manual `CLEAR`: forget the hang count and the last trial failure.
     * `InvalidArgument` during a run, whose result it would erase. Errors
     * otherwise as for starting.
     */
    fun `coreVregManualClear`()
    
    /**
     * Manual `SET` from the Advanced page. `value` 0 is the reset to the
     * build default; anything else has the flow's limits and confirmation.
     * Read back by later polls, as a commit. Errors as for starting.
     */
    fun `coreVregManualSet`(`value`: kotlin.UByte, `typed`: kotlin.String?)
    
    /**
     * Manual `TRIAL`, with the flow's limits and confirmation. It shows as a
     * found trial on the next poll. Errors as for starting.
     */
    fun `coreVregManualTrial`(`value`: kotlin.UByte, `typed`: kotlin.String?)
    
    /**
     * `EXT_CORE_VREG` write: `op` 0 set (value = VREG code, 0 = build
     * default), 1 trial, 2 end trial, 3 auto (value 0/1), 4 clear
     * (`dspi_proto::ext::VregOp`).
     *
     * Checked before anything is sent (`InvalidArgument`, no traffic): an
     * unknown op; a SET below the build default (the floor,
     * `CoreVregInfo::default_vreg`) or above 0x0F (1.30 V); a TRIAL outside
     * 0x0C..=0x0F (1.15-1.30 V); an AUTO value other than 0 or 1. The value
     * of TRIAL_END and CLEAR is ignored (sent as 0). Read the status back
     * with [`DspiCore::fetch_core_vreg`].
     *
     * WP CG14: a SET or TRIAL reads the unit's status first and goes through
     * `dspi_session::overvolt`: a raise above 1.20 V from what it reports now
     * needs `word`, exactly `OVERVOLT`, or nothing is written. This is the
     * one path to 1.30 V; the GUIs' flow stops at 1.25 V (`core_vreg_cal_*`).
     *
     * Errors: `OvervoltWordRequired` as above; `Disconnected`; `ReadOnly` on
     * a read-only connection;
     * `Unsupported` when the device has no usable core-voltage extension;
     * `Refused { status: EXT_WRITE_REFUSED }` when the device stalls the
     * request anyway; `Denied`, `Locked` or `Transfer` from the link.
     */
    fun `coreVregOp`(`op`: kotlin.UByte, `value`: kotlin.UByte, `word`: kotlin.String?)
    
    /**
     * End a trial, or abort a run, with `TRIAL_END`, at any time but while a
     * save is being read back. Works without a fresh status, so a run can be
     * aborted while reads are failing. `Disconnected` and `ReadOnly` change
     * nothing. A write that fails otherwise is not retried: later polls end
     * in `Ended`, or in `VerifyFailed`, from which it can be asked for again.
     */
    fun `coreVregTrialEnd`()
    
    /**
     * The crossfeed's custom pair (frequency and feed) as the device keeps
     * it: what Custom runs. Under a named preset `get_state` gives that
     * preset's values instead; this gives the custom pair whatever the
     * preset, from the mirror (no transfer). It is what
     * `set_crossfeed_freq`/`set_crossfeed_feed` write, an export saves, and
     * `config_diff`/`config_preview` compare.
     *
     * Errors: [`DspiError::Disconnected`] with no device.
     */
    fun `crossfeedCustomPair`(): CrossfeedPair
    
    /**
     * One control-surface operation, JSON `{op, index, ...}` (the old
     * core's ops, which the Qt `CsController` sends): `refresh`,
     * `refreshStatus`, `binding`, `name`, `ir`, `group`, `macro`,
     * `displayConfig`, `displayPage`, `displayStatus`, `save`, `revert`,
     * `learnArm`, `learnCancel`, `learnRead`, `macroFire`, `macroCancel`,
     * `auxState`, `auxLevel`, `auxRead`. Each write re-reads what it
     * changed; the first operation on a device not yet fetched fetches it.
     *
     * Returns JSON `{ok, status}` (the device's status code; `0x16` = still
     * pending) plus op-specific fields, or `{ok: false, error}` for a
     * malformed operation (bad JSON, a number out of its field's range, an
     * index the device does not have, an unknown op), a write on a
     * read-only connection (nothing is sent), firmware without control
     * surfaces, no device, or a transfer failure. `save` writes flash: the
     * bridge gates it (DangerousOps).
