            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_dspi_core_fn_free_notifylistener(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_dspi_core_fn_clone_notifylistener(pointer!!, status)
        }
    }

    
    /**
     * Packets arrived. Called on the notification reader's thread.
     */override fun `onNotifications`()
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_dspi_core_fn_method_notifylistener_on_notifications(
        it, _status)
}
    }
    
    

    

    
    
    companion object
    
}


