/**
 * One filter band as the device stores it: a PEQ band or a crossover slot.
 *
 * The meaning of `gain` and `qp` depends on the type: a Linkwitz Transform
 * (type 11) carries its target corner `fp` in `gain` and its target Q in
 * `qp`; every other type ignores `qp`.
 */
data class FilterParams (
    /**
     * The firmware's filter type byte (`FILTER_*`): 0 flat, 1..13 the PEQ
     * shapes, 32..63 the crossover family/order/pass codes.
     */
    var `filterType`: kotlin.UByte, 
    /**
     * True when the band is switched off without losing its settings.
     */
    var `bypass`: kotlin.Boolean, 
    /**
     * Centre or corner frequency in Hz (`f0` for a Linkwitz Transform).
     */
    var `freq`: kotlin.Float, 
    /**
     * Quality factor (`Q0` for a Linkwitz Transform).
     */
    var `q`: kotlin.Float, 
    /**
     * Gain in dB; the target corner `fp` in Hz for a Linkwitz Transform.
     */
    var `gain`: kotlin.Float, 
    /**
     * The Linkwitz Transform's target Q; unused by the other types.
     */
    var `qp`: kotlin.Float
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFilterParams: FfiConverterRustBuffer<FilterParams> {
    override fun read(buf: ByteBuffer): FilterParams {
        return FilterParams(
            FfiConverterUByte.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterFloat.read(buf),
        )
    }

    override fun allocationSize(value: FilterParams) = (
            FfiConverterUByte.allocationSize(value.`filterType`) +
            FfiConverterBoolean.allocationSize(value.`bypass`) +
            FfiConverterFloat.allocationSize(value.`freq`) +
            FfiConverterFloat.allocationSize(value.`q`) +
            FfiConverterFloat.allocationSize(value.`gain`) +
            FfiConverterFloat.allocationSize(value.`qp`)
    )

    override fun write(value: FilterParams, buf: ByteBuffer) {
            FfiConverterUByte.write(value.`filterType`, buf)
            FfiConverterBoolean.write(value.`bypass`, buf)
            FfiConverterFloat.write(value.`freq`, buf)
            FfiConverterFloat.write(value.`q`, buf)
            FfiConverterFloat.write(value.`gain`, buf)
            FfiConverterFloat.write(value.`qp`, buf)
    }
}



