/**
 * The result of [`firmware_guard_check`]. The default blocks.
 */
data class FirmwareGuardVerdict (
    /**
     * True only for `Clear` and `Confirmed`. Anything else must not flash.
     */
    var `allowed`: kotlin.Boolean, 
    /**
     * The decision.
     */
    var `decision`: FirmwareGuardDecision, 
    /**
     * Why.
     */
    var `reason`: FirmwareGuardReason, 
    /**
     * For the user, in English.
     */
    var `message`: kotlin.String, 
    /**
     * What to ask the user to type when a risk is involved, else "": the
     * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
     * exactly: case and spaces count, and the one does not stand for the other.
     */
    var `confirmationPhrase`: kotlin.String, 
    /**
     * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
     */
    var `imageMv`: kotlin.UShort, 
    /**
     * The board record's `required_mv`, as given.
     */
    var `requiredMv`: kotlin.UShort
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFirmwareGuardVerdict: FfiConverterRustBuffer<FirmwareGuardVerdict> {
    override fun read(buf: ByteBuffer): FirmwareGuardVerdict {
        return FirmwareGuardVerdict(
            FfiConverterBoolean.read(buf),
            FfiConverterTypeFirmwareGuardDecision.read(buf),
            FfiConverterTypeFirmwareGuardReason.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterUShort.read(buf),
            FfiConverterUShort.read(buf),
        )
    }

    override fun allocationSize(value: FirmwareGuardVerdict) = (
            FfiConverterBoolean.allocationSize(value.`allowed`) +
            FfiConverterTypeFirmwareGuardDecision.allocationSize(value.`decision`) +
            FfiConverterTypeFirmwareGuardReason.allocationSize(value.`reason`) +
            FfiConverterString.allocationSize(value.`message`) +
            FfiConverterString.allocationSize(value.`confirmationPhrase`) +
            FfiConverterUShort.allocationSize(value.`imageMv`) +
            FfiConverterUShort.allocationSize(value.`requiredMv`)
    )

    override fun write(value: FirmwareGuardVerdict, buf: ByteBuffer) {
            FfiConverterBoolean.write(value.`allowed`, buf)
            FfiConverterTypeFirmwareGuardDecision.write(value.`decision`, buf)
            FfiConverterTypeFirmwareGuardReason.write(value.`reason`, buf)
            FfiConverterString.write(value.`message`, buf)
            FfiConverterString.write(value.`confirmationPhrase`, buf)
            FfiConverterUShort.write(value.`imageMv`, buf)
            FfiConverterUShort.write(value.`requiredMv`, buf)
    }
}



/**
 * One change in the history ([`DspiCore::history`]).
 */
data class HistoryEntry (
    /**
     * The registry path (`out.gain`, `eq.freq`, ...), or one of the
     * journal's own: `eq.band` (a whole band: type, bypass, then freq, Q,
     * gain and the Linkwitz target Q as little-endian `f32`s), `ext.pairmap`
     * (the crossfeed pair map's four bytes), `ext.vreg` (a core-voltage
     * request: op and value), `raw` (a raw request: opcode and `wValue` as
     * indices, the payload as the value), `ext.alink.slots` (the 8
     * slot bytes), `ext.alink.phase` (mode, then the delay and the
     * hops offset as little-endian 16-bit values), `ext.alink.apply`
     * (op and arg as indices, the 16-byte request as the value) and
     * `ext.alink.stats_reset`. A control-surface operation is
     * under its `cs.*` path with the operation's JSON as text.
     */
    var `path`: kotlin.String, 
    /**
     * The path's indices (an output, a channel and a band, ...).
     */
    var `indices`: kotlin.ByteArray, 
    /**
     * The value before, when known; undo writes it back.
     */
    var `before`: ParamValue?, 
    /**
     * The value after (`trigger` for an action).
     */
    var `after`: ParamValue, 
    /**
     * Who made it.
     */
    var `source`: HistorySource, 
    /**
     * When, in milliseconds since the Unix epoch (a drag: its last step).
     */
    var `atMs`: kotlin.ULong, 
    /**
     * Whether undo may reverse it. The registry decides: only a parameter
     * with no hazard (not a flash write, an audible one, a reconfiguration,
     * a deferred or an irreversible one).
     */
    var `undoable`: kotlin.Boolean, 
    /**
     * The undo group's label ([`DspiCore::begin_group`]) when the change
     * was written inside one; `None` otherwise.
     */
    var `label`: kotlin.String?
) {
    
    companion object
}

