/**
 * A parameter value: `dspi_proto::value::Value` across the bindings. In
 * JSON (the C ABI, the web binding) it is tagged by kind in lower case:
 * `{"float": -12.5}`, `{"bool": true}`, `{"bytes": [1, 2]}`, `"trigger"`.
 */
sealed class ParamValue {
    
    /**
     * A yes/no value.
     */
    data class Bool(
        val v1: kotlin.Boolean) : ParamValue() {
        companion object
    }
    
    /**
     * A number.
     */
    data class Float(
        val v1: kotlin.Float) : ParamValue() {
        companion object
    }
    
    /**
     * A whole number.
     */
    data class Int(
        val v1: kotlin.Long) : ParamValue() {
        companion object
    }
    
    /**
     * A choice, as its wire number (the registry has the labels).
     */
    data class Choice(
        val v1: kotlin.UByte) : ParamValue() {
        companion object
    }
    
    /**
     * A bit mask.
     */
    data class Mask(
        val v1: kotlin.UInt) : ParamValue() {
        companion object
    }
    
    /**
     * Text.
     */
    data class Text(
        val v1: kotlin.String) : ParamValue() {
        companion object
    }
    
    /**
     * A structured payload, as the registry's packet encodes it.
     */
    data class Bytes(
        val v1: kotlin.ByteArray) : ParamValue() {
        companion object
    }
    
    /**
     * An action with no value.
     */
    object Trigger : ParamValue()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeParamValue : FfiConverterRustBuffer<ParamValue>{
    override fun read(buf: ByteBuffer): ParamValue {
        return when(buf.getInt()) {
            1 -> ParamValue.Bool(
                FfiConverterBoolean.read(buf),
                )
            2 -> ParamValue.Float(
                FfiConverterFloat.read(buf),
                )
            3 -> ParamValue.Int(
                FfiConverterLong.read(buf),
                )
            4 -> ParamValue.Choice(
                FfiConverterUByte.read(buf),
                )
            5 -> ParamValue.Mask(
                FfiConverterUInt.read(buf),
                )
            6 -> ParamValue.Text(
                FfiConverterString.read(buf),
                )
            7 -> ParamValue.Bytes(
                FfiConverterByteArray.read(buf),
                )
            8 -> ParamValue.Trigger
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ParamValue) = when(value) {
        is ParamValue.Bool -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.v1)
            )
        }
        is ParamValue.Float -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterFloat.allocationSize(value.v1)
            )
        }
        is ParamValue.Int -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.v1)
            )
        }
        is ParamValue.Choice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.v1)
            )
        }
        is ParamValue.Mask -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.v1)
            )
        }
        is ParamValue.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
        is ParamValue.Bytes -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.v1)
            )
        }
        is ParamValue.Trigger -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: ParamValue, buf: ByteBuffer) {
        when(value) {
            is ParamValue.Bool -> {
                buf.putInt(1)
                FfiConverterBoolean.write(value.v1, buf)
                Unit
            }
            is ParamValue.Float -> {
                buf.putInt(2)
                FfiConverterFloat.write(value.v1, buf)
                Unit
            }
            is ParamValue.Int -> {
                buf.putInt(3)
                FfiConverterLong.write(value.v1, buf)
                Unit
            }
            is ParamValue.Choice -> {
                buf.putInt(4)
                FfiConverterUByte.write(value.v1, buf)
                Unit
            }
            is ParamValue.Mask -> {
                buf.putInt(5)
                FfiConverterUInt.write(value.v1, buf)
                Unit
            }
            is ParamValue.Text -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ParamValue.Bytes -> {
                buf.putInt(7)
                FfiConverterByteArray.write(value.v1, buf)
                Unit
            }
            is ParamValue.Trigger -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Where a run is: [`VregCalView::phase`]. The details are in the view.
 */

enum class VregCalPhase {
    
    /**
     * The flow is not open.
     */
    IDLE,
    /**
     * Open: show the warning and what the device has on record.
     */
    REVIEW,
    /**
     * Clearing the device's record before the trial.
     */
    CLEARING,
    /**
     * The trial was sent and is not seen running yet.
     */
    STARTING_TRIAL,
    /**
     * The trial runs; the soak is counting. Abort is available.
     */
    SOAKING,
    /**
     * Passed: the trial still runs and nothing is saved. Commit or end.
     */
    PASSED,
    /**
     * The trial hung: `failed_vreg`, `ran_s`, `next_vreg`, `hardware_problem`.
     */
    FAILED,
    /**
     * The result cannot be known: run again.
     */
    UNKNOWN,
    /**
     * A trial nobody here started is running: end or keep.
     */
    TRIAL_FOUND,
    /**
     * A kept trial outside the flow's range: left alone, cannot pass.
     */
    TRIAL_LEFT_RUNNING,
    /**
     * Ending the trial.
     */
    ENDING,
    /**
     * The trial ended.
     */
    ENDED,
    /**
     * Saving: waiting to read the voltage back.
     */
    COMMITTING,
    /**
     * Saved and read back.
     */
    COMMITTED,
    /**
     * A save or an end did not show in time. Nothing was retried.
     */
    VERIFY_FAILED;
    companion object
}


